// cover-fonts.js — the three typefaces of the EngiKode site, cut down to plain letters, figures and a few marks (about 46 KB), as @font-face
// rules with the fonts inside them. The promo cover (cover.js) is shown with scripts off, in a frame that may be offline or being printed,
// so it cannot wait for a web font to arrive. Manrope 600 and 800, DM Mono 500, Source Serif 4 italic 600; all SIL Open Font Licence.
// Made once from Google Fonts with the `text=` option; letters outside it fall back to the system font.
export const COVER_FONTS = "@font-face{font-family:'Manrope';font-style:normal;font-weight:600;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Manrope';font-style:normal;font-weight:800;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'DM Mono';font-style:normal;font-weight:500;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Source Serif 4';font-style:italic;font-weight:600;src:url(data:font/woff2;base64,) format('woff2')}";
